import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const OUT = "/tmp/claude-0/-home-user-EdFringeNow/4cb679a0-2a8c-5c38-9a33-6df442d42030/scratchpad";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });

await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8777/plan/", { waitUntil: "networkidle" });
await page.click("#debugPill");
await page.click("#debugRandomBtn");
await page.waitForSelector("#screen2:not([hidden])", { timeout: 30000 });
await page.waitForFunction(() => document.querySelectorAll("#lanes .cal-row").length > 0, { timeout: 30000 });
await page.waitForTimeout(1500);

const card = page.locator("#screen2");

await page.mouse.move(20, 20);
await page.waitForTimeout(600);
const idle = await card.boundingBox();
await card.screenshot({ path: `${OUT}/legend2-idle.png` });

// Hover the grid but keep off the day cells (left name column) so no tooltip.
const wrap = await page.locator("#calWrap").boundingBox();
await page.mouse.move(wrap.x + 60, wrap.y + wrap.height - 20);
await page.waitForTimeout(600);
const hover = await card.boundingBox();
await card.screenshot({ path: `${OUT}/legend2-hover.png` });

const gap = await page.evaluate(() => {
  const w = document.getElementById("calWrap").getBoundingClientRect();
  const l = document.getElementById("calLegend").getBoundingClientRect();
  const c = document.getElementById("screen2").getBoundingClientRect();
  return { gridToLegend: +(l.top - w.bottom).toFixed(1), legendH: +l.height.toFixed(1),
           legendToCardEdge: +(c.bottom - l.bottom).toFixed(1) };
});
console.log("card height idle:", idle.height, "hover:", hover.height,
  idle.height === hover.height ? "→ NO SHIFT" : "→ SHIFTED");
console.log(gap);

await browser.close();

